<script lang="ts">
 import {untrack,onMount} from 'svelte';
 import {api} from './api';
 import {indentReference} from './sampleProcess';
 import {Download} from '@lucide/svelte';
 let {company,mode,revision=0,onedit,onopen,onchanged=()=>{}}:{company:string;mode:string;revision?:number;onedit?:(rows:any[])=>void;onopen:(id:number,indent?:number)=>void;onchanged?:()=>void}=$props();
 let result:any=$state(null),line=$state(''),from=$state(''),to=$state(''),lines:string[]=$state([]),busy=$state(false),mutating=$state(false),error=$state(''),notice=$state(''),exporting=$state(false),cancelPlan:any=$state(null),reason=$state(''),applied=$state('');
 let generation=0;
 let deadlines:Record<number,string>=$state({});
 const groups=$derived.by(()=>{const map=new Map<number,any[]>();for(const r of result?.rows||[]){if(!map.has(r.plan_id))map.set(r.plan_id,[]);map.get(r.plan_id)!.push(r)}return [...map.values()]});
 const lineName=(v:string)=>v==='General'?'Non-production (legacy)':v;
 async function load(){const n=++generation;const query=new URLSearchParams({company,view:mode,resource:line,from,to}).toString();busy=true;error='';try{const [r,c]=await Promise.all([api('/sample-plans?'+query),api('/sample-capacities')]);if(n!==generation)return;result=r;applied=query;lines=[...new Set<string>([...c.records.filter((v:any)=>String(v.company_id)===company).map((v:any)=>v.resource),...r.rows.map((v:any)=>v.resource)])]}catch(e){if(n===generation)error=(e as Error).message}finally{if(n===generation)busy=false}}
 $effect(()=>{company;mode;revision;untrack(()=>{line='';from='';to='';deadlines={};result=null;notice='';cancelPlan=null;load()})});
 // Deadline movement is derived by the API in IST, including a tab left open overnight.
 onMount(()=>{const timer=setInterval(()=>{if(!document.hidden&&!busy&&!mutating&&!cancelPlan)load()},60000);return()=>{clearInterval(timer);generation++}});
 async function action(plan:any,action:string){if(mutating)return;const scope=company;mutating=true;error='';notice='';try{await api('/sample-plans',{company_id:Number(company),id:plan.plan_id,version:plan.plan_version,action,reason,deadline:action==='freeze'?(deadlines[plan.plan_id]??plan.deadline):undefined});if(company!==scope)return;cancelPlan=null;reason='';notice=action==='freeze'?'Plan frozen. Its dates are fixed and its indents are no longer in Planning.':'Plan cancelled. Its capacity and indents are available for planning again.';await load();onchanged()}catch(e){if(company===scope)error=(e as Error).message}finally{mutating=false}}
 async function exportExcel(){if(exporting||busy||!applied)return;const scope=company;exporting=true;error='';try{const res=await fetch('/api/sample-plans?'+applied+'&format=xlsx',{cache:'no-store'});if(!res.ok){const p=await res.json().catch(()=>null);throw new Error(p?.error||'Unable to export the report.')}const blob=await res.blob();if(scope!==company)return;const url=URL.createObjectURL(blob),a=document.createElement('a');a.href=url;a.download='sample-freeze-master.xlsx';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}catch(e){if(company===scope)error=(e as Error).message}finally{exporting=false}}
 function variance(r:any){if(r.outcome==='Early')return `${Math.abs(r.variance_days)} days early`;if(['Late','Overdue'].includes(r.outcome))return `${r.variance_days} days ${r.outcome==='Late'?'late':'overdue'}`;return r.outcome}
 function canManage(rows:any[]){return result?.can_plan&&rows.length===rows[0].item_count}
</script>
<section class="plan-ledger" aria-label={mode==='planning'?'Reserved plans':mode==='freezing'?'Freezing':'Freeze Master'}>
 <header><div><h3>{mode==='planning'?'Reserved plans':mode==='freezing'?'Freezing':'Freeze Master'}</h3><p>{mode==='planning'?'Saved plans already reserve capacity. Edit their priority or dates before freezing.':mode==='freezing'?'Freeze a saved plan to lock its dates. After its deadline, it moves to Freeze Master automatically.':'Frozen plans whose deadlines have passed. Actual final handover determines early or late delivery; unfinished work stays overdue.'}</p></div>{#if mode==='freeze-master'}<button class="button secondary" disabled={busy||exporting||!result?.rows.length} onclick={exportExcel}><Download size={16}/>{exporting?'Preparing…':'Export Excel'}</button>{/if}</header>
 <form class="ledger-filters" onsubmit={e=>{e.preventDefault();load()}}><label>Sample line<select bind:value={line}><option value="">All lines</option>{#each lines as name}<option value={name}>{lineName(name)}</option>{/each}</select></label><label>Deadline from<input type="date" bind:value={from}/></label><label>Deadline to<input type="date" bind:value={to}/></label><button class="button secondary" disabled={busy}>Apply filters</button></form>
 {#if error}<p class="form-error" role="alert">{error}</p>{/if}{#if notice}<p role="status" class="ledger-notice">{notice}</p>{/if}
 {#if cancelPlan}<form class="cancel-plan" onsubmit={e=>{e.preventDefault();action(cancelPlan,'cancel')}}><label>Reason for cancelling plan #{cancelPlan.plan_id}<input required minlength="3" maxlength="1000" bind:value={reason}/></label><button class="button secondary" type="button" disabled={mutating} onclick={()=>cancelPlan=null}>Keep plan</button><button class="button primary" disabled={mutating}>Release reserved capacity</button></form>{/if}
 {#each groups as items (items[0].plan_id)}{@const plan=items[0]}
 <article class="ledger-plan">
  <div class="ledger-plan-heading"><div><h4>{lineName(plan.resource)} <span>Plan #{plan.plan_id}</span></h4><p>{plan.requested_start} → {plan.deadline} · {items.reduce((n,r)=>n+r.units,0)} visible pieces · Planned by {plan.planned_by}</p>{#if plan.frozen_by}<p>Frozen by {plan.frozen_by} · {new Date(plan.frozen_at).toLocaleString('en-IN',{timeZone:'Asia/Kolkata'})} IST</p>{/if}</div><div class="ledger-actions"><span class="plan-state" class:frozen={plan.state==='Frozen'}>{plan.state==='Planned'?'Reserved · awaiting freeze':'Frozen'}</span>{#if plan.state==='Planned'&&canManage(items)}{#if mode==='freezing'}<label>Freeze deadline<input type="date" min={plan.deadline} value={deadlines[plan.plan_id]??plan.deadline} oninput={e=>deadlines[plan.plan_id]=e.currentTarget.value}/></label><button class="button primary" disabled={mutating||busy||(deadlines[plan.plan_id]??plan.deadline)<plan.deadline} onclick={()=>action(plan,'freeze')}>{mutating?'Saving…':'Freeze plan'}</button>{/if}{#if onedit}<button class="button secondary" disabled={mutating||busy} onclick={()=>onedit?.(items)}>Edit priority / dates</button>{/if}<button class="text-button" disabled={mutating||busy} onclick={()=>{cancelPlan=plan;reason=''}}>Cancel plan</button>{/if}</div></div>
  <div class="ledger-scroll"><table><thead><tr><th>S.No</th><th>Indent / buyer</th><th>Style / size / colour</th><th>Pieces</th><th>Reserved dates</th><th>Final handover</th><th>Delivery</th><th>Action</th></tr></thead><tbody>{#each items as r}<tr><td class="serial">{r.position}</td><td><strong>{indentReference(r)}</strong><small>{r.buyer}</small></td><td><strong>{r.profile.buyer_style||'—'}</strong><small>{r.size||'Size not recorded'} · {r.colour||'Colour not recorded'}</small></td><td>{r.units}</td><td><strong>{r.start_date} → {r.plan_date}</strong><details><summary>Daily allocation</summary>{#each r.allocations||[] as a}<small>{a.date}: {a.units} pcs</small>{/each}</details></td><td>{r.production.handover_actual?new Date(r.production.handover_actual).toLocaleDateString('en-IN',{timeZone:'Asia/Kolkata'}):'Not handed over'}<small>{r.status}</small></td><td><span class="delivery" class:late={['Late','Overdue'].includes(r.outcome)} class:done={['Early','On time'].includes(r.outcome)}>{variance(r)}</span></td><td><button class="button secondary" onclick={()=>onopen(r.request_id,r.id)}>View</button></td></tr>{/each}</tbody></table></div>
 </article>{:else}<p class="ledger-empty">{busy?'Loading plans…':mode==='planning'?'No reserved plans. Select indents below to prepare a plan.':mode==='freezing'?'No plans to freeze or active frozen plans. Save a plan in Planning first.':'No expired frozen plans match these filters.'}</p>{/each}
</section>
<style>
 .plan-ledger{color:#17212f;margin-bottom:20px}.plan-ledger>header{display:flex;justify-content:space-between;align-items:start;gap:16px;padding:12px 0}.plan-ledger h3{font-size:16px;margin:0;font-weight:700}.plan-ledger p{font-size:13px;line-height:1.5;color:#374151;margin:5px 0}.ledger-filters{display:flex;gap:12px;align-items:end;margin:8px 0 16px}.plan-ledger label{display:grid;gap:6px;font-size:13px;font-weight:600;color:#17212f}.plan-ledger :is(input,select){min-height:44px;min-width:160px;max-width:100%;padding:9px 12px;border:1px solid #c7d2dd;border-radius:10px;background:#f6f8fa;color:#111;font:inherit}.ledger-plan{border:1px solid #dce3e9;border-radius:16px;overflow:hidden;margin:12px 0;background:#fff}.ledger-plan-heading{display:flex;justify-content:space-between;gap:16px;align-items:center;padding:12px 16px;background:#f8fafb}.ledger-plan h4{margin:0;font-size:15px;font-weight:700}.ledger-plan h4 span{font-size:12px;font-weight:600;color:#435568;margin-left:8px}.ledger-plan-heading p{font-size:12px}.ledger-actions{display:flex;gap:8px;align-items:center;flex-wrap:wrap;justify-content:flex-end}.plan-state,.delivery{display:inline-block;padding:5px 8px;border:1px solid #e6d3a4;border-radius:8px;background:#fffaeb;color:#79520c;font-size:12px;font-weight:600;white-space:nowrap}.plan-state.frozen{background:#edf4fa;border-color:#bbd0e2;color:#234b6c}.ledger-scroll{overflow:auto}table{width:100%;min-width:880px;border-collapse:collapse;font-size:13px}th,td{text-align:left;padding:8px 9px;border-top:1px solid #e4e9ee;color:#17212f;vertical-align:middle}th{background:#fff;font-size:12px;color:#374151;font-weight:700}small{display:block;font-size:12px;color:#374151;line-height:1.5;margin-top:3px}.serial{font-variant-numeric:tabular-nums;font-weight:700}.delivery{background:#f4f6f8;border-color:#d7dfe7;color:#374151}.delivery.late{background:#fff0ed;border-color:#e6b8af;color:#952d20}.delivery.done{background:#edf9f1;border-color:#b6dcca;color:#14613b}.ledger-empty{padding:16px;background:#f8fafb;border:1px solid #dce3e9;border-radius:12px}.plan-ledger .ledger-notice{padding:12px;background:#edf9f1;color:#14613b;border-radius:10px}.cancel-plan{display:flex;gap:12px;align-items:end;padding:12px;background:#fff8eb;border:1px solid #e6d3a4;border-radius:12px}.cancel-plan label{flex:1}.ledger-plan summary{cursor:pointer;font-size:12px;min-height:28px;padding:5px 0;color:#075e5a}.plan-ledger :is(button,input,select,summary):focus-visible{outline:3px solid #08776e;outline-offset:2px}
</style>
